 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Separator color occurs on full-width separator rows and full-height columns.
    separator = next(grid[r][0] for r in range(h) if all(v == grid[r][0] for v in grid[r]))
    row_groups, col_groups = [], []
    for r in range(h):
        if all(v == separator for v in grid[r]):
            continue
        if not row_groups or r != row_groups[-1][-1] + 1:
            row_groups.append([r])
        else:
            row_groups[-1].append(r)
    for c in range(w):
        if all(grid[r][c] == separator for r in range(h)):
            continue
        if not col_groups or c != col_groups[-1][-1] + 1:
            col_groups.append([c])
        else:
            col_groups[-1].append(c)

    from collections import Counter
    colors = Counter(v for row in grid for v in row if v != separator)
    background = colors.most_common(1)[0][0]
    marker = next(color for color in colors if color != background)
    return [[1 if sum(grid[r][c] == marker for r in rg for c in cg) >= 2 else background
             for cg in col_groups] for rg in row_groups]

